select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_ASSEMBLY_SCALE_API','RRL_SCALE_PACKET_READ','RRL_CASE_SCALE_ADMISSION','RRL_STOCK_CASE_PICK_CMD');
select NAME,TYPE,LINE,TEXT from USER_ERRORS where NAME in('RRL_ASSEMBLY_SCALE_API','RRL_SCALE_PACKET_READ','RRL_CASE_SCALE_ADMISSION','RRL_STOCK_CASE_PICK_CMD')or NAME like 'RRL_ASM_%GUARD';
select count(*) INVALID_COUNT from USER_OBJECTS where STATUS='INVALID';
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-15-incremental-assembly';
